var builder = new SyncRequest.Builder();
builder.SetSyncAdapter(account, authority);
builder.SyncOnce();
foreach (string item in new[] { "dog", "cat", "frog", "child" })
{
    var extras = new Bundle();
    extras.PutString("data", item);
    builder.SetExtras(extras);
    ContentResolver.RequestSync(builder.Build());
}

var fiveHourBuilder = new SyncRequest.Builder();
fiveHourBuilder.SyncPeriodic(5 * 60 * 60, 20 * 60);
var hourlyBuilder = new SyncRequest.Builder();
hourlyBuilder.SyncPeriodic(60 * 60, 60 * 60);
